CREATE FUNCTION public.games_tsvector_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
new.document :=
setweight(to_tsvector('english', coalesce(new.name, '')), 'A')
|| setweight(to_tsvector('english', coalesce(new.description, '')), 'B');
return new;
end
$$;


